template <int NB_X, typename T, typename I, typename U>
ROCSOLVER_KERNEL void __launch_bounds__(NB_X) larf_right_kernel(
    const I m, const I n, U xx, const rocblas_stride shiftX, const I incX,
    const rocblas_stride strideX, const T* tauA, const rocblas_stride strideP,
    U AA, const rocblas_stride shiftA, const I lda, const rocblas_stride strideA)
{
    I bid = blockIdx.z;
    I tx = threadIdx.x;
    I row = blockIdx.y;

    T* x = load_ptr_batch<T>(xx, bid, shiftX, strideX);
    T* A = load_ptr_batch<T>(AA, bid, shiftA, strideA);
    const T* tau = tauA + bid * strideP;

    A += row;  // start of row
    I start = (incX > 0 ? 0 : (n - 1) * -incX);

    extern __shared__ double smem[];
    T* sdata = reinterpret_cast<T*>(smem);
    T* xs = sdata + (NB_X / warpSize);

    // Cache x vector in LDS
    for(I i = tx; i < n; i += NB_X)
        xs[i] = x[start + i * size_t(incX)];

    T res = 0;
    // GEMV: res = A_row * conj(x)
    for(I i = tx; i < n; i += NB_X)
        res += A[i * size_t(lda)] * conj(xs[i]);

    // Warp reduction
    res += shift_left(res, 1);
    res += shift_left(res, 2);
    res += shift_left(res, 4);
    res += shift_left(res, 8);
    res += shift_left(res, 16);
    if(warpSize > 32)
        res += shift_left(res, 32);
    if(tx % warpSize == 0)
        sdata[tx / warpSize] = res;
    __syncthreads();

    if(tx == 0) {
        for(I k = 1; k < NB_X / warpSize; k++)
            res += sdata[k];
        sdata[0] = res;
    }
    __syncthreads();

    // GER: A_row := A_row - tau * sdata[0] * conj(x)
    res = -tau[0] * sdata[0];
    for(I i = tx; i < n; i += NB_X)
        A[i * size_t(lda)] += res * conj(xs[i]);
}
```

Key differences from left kernel: (1) A indexed by `i*lda` for row access, (2) conjugate on x instead of A.

