Fused kernel design:

```cpp
template <int NB_X, typename T, typename I, typename U>
ROCSOLVER_KERNEL void __launch_bounds__(NB_X) 
larf_left_fused_diag_kernel(
    const I m, const I n, const I j,
    U xx, const rocblas_stride shiftX, const I incX, const rocblas_stride strideX,
    const T* tauA, const rocblas_stride strideP,
    U AA, const rocblas_stride shiftA, const I lda, const rocblas_stride strideA,
    T* D, const rocblas_stride strideD)
{
    I bid = blockIdx.z;
    I tx = threadIdx.x;
    I col = blockIdx.y;

    T* x = load_ptr_batch<T>(xx, bid, shiftX, strideX);
    T* A = load_ptr_batch<T>(AA, bid, shiftA, strideA);
    const T* tau = tauA + bid * strideP;
    T* D_batch = D + bid * strideD;

    A += col * size_t(lda);

    extern __shared__ double smem[];
    T* sdata = reinterpret_cast<T*>(smem);
    T* xs = sdata + (NB_X / warpSize);
    __shared__ T saved_diag;

    // Step 1: Thread 0 saves diagonal (only once per block)
    if(tx == 0 && col == 0) {
        saved_diag = A[0];  // A(j,j) before modification
        D_batch[j] = saved_diag;
        A[0] = 1;  // set for Householder application
    }
    __syncthreads();

    // Step 2: Cache x vector in LDS
    I start = (incX > 0 ? 0 : (m - 1) * -incX);
    for(I i = tx; i < m; i += NB_X)
        xs[i] = x[start + i * size_t(incX)];

    // Step 3: GEMV + reduction (same as larf_left_kernel)
    T res = 0;
    for(I i = tx; i < m; i += NB_X)
        res += conj(A[i]) * xs[i];

    // Warp reduction
    res += shift_left(res, 1);
    res += shift_left(res, 2);
    res += shift_left(res, 4);
    res += shift_left(res, 8);
    res += shift_left(res, 16);
    if(warpSize > 32) res += shift_left(res, 32);

    if(tx % warpSize == 0)
        sdata[tx / warpSize] = res;
    __syncthreads();

    if(tx == 0) {
        for(I k = 1; k < NB_X / warpSize; k++)
            res += sdata[k];
        sdata[0] = res;
    }
    __syncthreads();

    // Step 4: GER update
    res = -tau[0] * conj(sdata[0]);
    for(I i = tx; i < m; i += NB_X)
        A[i] += res * xs[i];
    __syncthreads();

    // Step 5: Thread 0 restores diagonal (last column only)
    if(tx == 0 && col == n - j - 2) {  // last column processed
        A[-col * lda] = saved_diag;  // restore A(j,j)
    }
}
```

**Benefits:**
- Reduces 3 kernel launches to 1 per iteration (saves ~2μs launch overhead)
- Eliminates global memory write-read-write of diagonal element
- Saves diagonal in LDS instead of D array

**Challenges:**
- Requires coordination: first column block saves, last column block restores
- Need grid synchronization or use cooperative groups
- Complexity increases; harder to debug
- Current design with separate kernels is more modular

**Verdict:** Beneficial for small n (few columns) where launch overhead dominates. For large n, GEMM becomes dominant and fusion gains are minimal.

